# Link map for 30_link.bat (used on every PC)
# Format : <path relative to dotfiles root>|<destination>
# - %VAR% in destination is expanded at run time (USERPROFILE, APPDATA, NOTES_DIR ...)
# - Lines starting with # and blank lines are ignored
# - Do not indent entries

# Notepad++
# (only shortcuts and themes; app-rewritten files such as stylers.xml / NppExec.ini are not tracked)
windows\notepadpp\Gruvbox dark medium.xml|%USERPROFILE%\scoop\apps\notepadplusplus\current\themes\Gruvbox dark medium.xml
windows\notepadpp\Gruvbox light medium.xml|%USERPROFILE%\scoop\apps\notepadplusplus\current\themes\Gruvbox light medium.xml

# Windows (startup / terminal)
windows\startup\startup.bat|%APPDATA%\Microsoft\Windows\Start Menu\Programs\Startup\startup.bat
windows\autohotkey\Autohotkey64.ahk|%APPDATA%\Microsoft\Windows\Start Menu\Programs\Startup\Autohotkey64.ahk
windows\wsl\.wslconfig|%USERPROFILE%\.wslconfig
windows\terminal\settings.json|%USERPROFILE%\scoop\apps\windows-terminal\current\settings\settings.json

# git / shell / vim
home\.config\git\config|%USERPROFILE%\.config\git\config
home\.gitconfig|%USERPROFILE%\.gitconfig
home\.gitignore_global|%USERPROFILE%\.gitignore_global
home\.config\starship.toml|%USERPROFILE%\.config\starship.toml
home\.vimrc|%USERPROFILE%\.vimrc
windows\powershell\profile.ps1|%USERPROFILE%\Documents\PowerShell\profile.ps1

# VS Code (scoop persist) — 拡張一覧は manifests/vscode-extensions.*.txt
windows\vscode\settings.json|%USERPROFILE%\scoop\persist\vscode\data\user-data\User\settings.json
windows\vscode\keybindings.json|%USERPROFILE%\scoop\persist\vscode\data\user-data\User\keybindings.json

# Claude Code (user settings: permission base)
home\.claude\settings.json|%USERPROFILE%\.claude\settings.json

# draw.io / Zed
windows\drawio\config.json|%APPDATA%\draw.io\config.json
home\.config\zed\keymap.json|%APPDATA%\zed\keymap.json
home\.config\zed\settings.json|%APPDATA%\zed\settings.json
home\.config\zed\themes|%APPDATA%\zed\themes

# Vault (notes is a sibling repo of dotfiles and is itself the Obsidian vault root; it holds .obsidian too)
..\notes|%NOTES_DIR%
